package com.aoo.bcg.common.invite;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class SignedInviteServiceTest{@Test void signsAllRoutingFieldsAndRejectsTamperAndExpiry(){Instant now=Instant.parse("2026-08-23T00:00:00Z");byte[]key=new byte[32];java.util.Arrays.fill(key,(byte)7);var service=new SignedInviteService(key,new AuthoritativeTimeSource(Clock.fixed(now,ZoneOffset.UTC)));var payload=new InvitePayload(100,62,9,"invite_1234567890","njpdk-v2",now.plusSeconds(60));var token=service.sign(payload);assertEquals(payload,service.verify(token));assertThrows(SecurityException.class,()->service.verify(new SignedInviteService.SignedInvite(token.payload()+"x",token.signature())));var expired=new SignedInviteService(key,new AuthoritativeTimeSource(Clock.fixed(now.plusSeconds(61),ZoneOffset.UTC)));assertThrows(SecurityException.class,()->expired.verify(token));}}
